ALTER TABLE inv_form_usuarios ENABLE ROW LEVEL SECURITY;
ALTER TABLE inv_form_categorias ENABLE ROW LEVEL SECURITY;
ALTER TABLE inv_form_inventario ENABLE ROW LEVEL SECURITY;
ALTER TABLE inv_form_movimientos ENABLE ROW LEVEL SECURITY;
ALTER TABLE inv_form_det_movimientos ENABLE ROW LEVEL SECURITY;
ALTER TABLE inv_form_movimiento_fotos ENABLE ROW LEVEL SECURITY;
ALTER TABLE inv_form_solicitudes_prestamo ENABLE ROW LEVEL SECURITY;
ALTER TABLE inv_form_det_solicitudes ENABLE ROW LEVEL SECURITY;
ALTER TABLE inv_form_cuentadantes ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS inv_form_usuarios_all ON inv_form_usuarios;
DROP POLICY IF EXISTS inv_form_categorias_all ON inv_form_categorias;
DROP POLICY IF EXISTS inv_form_inventario_all ON inv_form_inventario;
DROP POLICY IF EXISTS inv_form_movimientos_all ON inv_form_movimientos;
DROP POLICY IF EXISTS inv_form_det_movimientos_all ON inv_form_det_movimientos;
DROP POLICY IF EXISTS inv_form_movimiento_fotos_all ON inv_form_movimiento_fotos;
DROP POLICY IF EXISTS inv_form_solicitudes_all ON inv_form_solicitudes_prestamo;
DROP POLICY IF EXISTS inv_form_det_solicitudes_all ON inv_form_det_solicitudes;
DROP POLICY IF EXISTS inv_form_cuentadantes_all ON inv_form_cuentadantes;

CREATE POLICY inv_form_usuarios_all ON inv_form_usuarios FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
CREATE POLICY inv_form_categorias_all ON inv_form_categorias FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
CREATE POLICY inv_form_inventario_all ON inv_form_inventario FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
CREATE POLICY inv_form_movimientos_all ON inv_form_movimientos FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
CREATE POLICY inv_form_det_movimientos_all ON inv_form_det_movimientos FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
CREATE POLICY inv_form_movimiento_fotos_all ON inv_form_movimiento_fotos FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
CREATE POLICY inv_form_solicitudes_all ON inv_form_solicitudes_prestamo FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
CREATE POLICY inv_form_det_solicitudes_all ON inv_form_det_solicitudes FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
CREATE POLICY inv_form_cuentadantes_all ON inv_form_cuentadantes FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);

GRANT ALL ON inv_form_usuarios, inv_form_categorias, inv_form_inventario, inv_form_movimientos,
  inv_form_det_movimientos, inv_form_movimiento_fotos, inv_form_solicitudes_prestamo,
  inv_form_det_solicitudes, inv_form_cuentadantes
  TO anon, authenticated;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO anon, authenticated;

NOTIFY pgrst, 'reload schema';
